    "id": "history-pp-2005-OR-F1",
    "subject": "history",
    "chapterId": "hist-eur2",
    "sectionId": "hist-section3",
    "source": "LC History Ordinary 2005 — F1 [REFERENCE — pre-current-syllabus]",
