    "id": "history-pp-2005-OR-F2",
    "subject": "history",
    "chapterId": "hist-eur5",
    "sectionId": "hist-section3",
    "source": "LC History Ordinary 2005 — F2 [REFERENCE — pre-current-syllabus]",
