    "id": "history-pp-2005-OR-F3",
    "subject": "history",
    "chapterId": "hist-eur2",
    "sectionId": "hist-section3",
    "source": "LC History Ordinary 2005 — F3 [REFERENCE — pre-current-syllabus]",
