    "id": "history-pp-2005-OR-C3",
    "subject": "history",
    "chapterId": "hist-ire3",
    "sectionId": "hist-section2",
    "source": "LC History Ordinary 2005 — C3 [REFERENCE — pre-current-syllabus]",
