    "id": "history-pp-2005-OR-E6",
    "subject": "history",
    "chapterId": "hist-eur4",
    "sectionId": "hist-section3",
    "source": "LC History Ordinary 2005 — E6 [REFERENCE — pre-current-syllabus]",
