    "id": "history-pp-2005-OR-F4",
    "subject": "history",
    "chapterId": "hist-eur3",
    "sectionId": "hist-section3",
    "source": "LC History Ordinary 2005 — F4 [REFERENCE — pre-current-syllabus]",
