    "id": "history-pp-2005-HI-B.3",
    "subject": "history",
    "chapterId": "hist-ire3",
    "sectionId": "hist-section2",
    "source": "LC History Higher 2005 — B.3 [REFERENCE — pre-current-syllabus]",
